-- =====================================================================
-- DJC rate list + Bayer price list 2026 (revised 1 Oct 2026)
-- 313 products for organization 1bce58f6-5c65-41e8-93f3-bd3ebb0adaeb
--
-- * MRP = DJC "FRP" / Bayer "Label MRP per pack". Purchase rate is left 0:
--   it is filled in when you record Stock In.
-- * Run in Supabase -> SQL Editor (after migration 005). Safe to run again:
--   existing products are not duplicated, and their MRP is updated to this list.
-- =====================================================================
do $$
declare
  v_org uuid := '1bce58f6-5c65-41e8-93f3-bd3ebb0adaeb';
begin
  if not exists (select 1 from public.organizations where id = v_org) then
    raise exception 'Organization % not found', v_org;
  end if;

  perform public.seed_categories(v_org);
  on conflict do nothing;

  create temp table _rate (company text, name text, category text, size numeric, unit public.pack_unit,
                           ptype public.pack_type, mrp numeric, note text) on commit drop;

  select distinct v_org, company from _rate
  on conflict do nothing;

  -- new products
  select v_org, r.name, c.id, co.id, r.size, r.unit, r.ptype, r.mrp, r.note
  from _rate r
  join public.categories c on c.org_id = v_org and c.name = r.category
  join public.companies co on co.org_id = v_org and co.name = r.company
  on conflict do nothing;

  -- products that already existed: bring MRP up to this list
  update public.products p
     set sale_price = r.mrp
    from _rate r
    join public.companies co on co.org_id = v_org and co.name = r.company
   where p.org_id = v_org and p.company_id = co.id
     and lower(trim(p.name)) = lower(trim(r.name)) and p.pack_size = r.size and p.pack_unit = r.unit
     and p.sale_price is distinct from r.mrp;
end $$;

-- Result
select co.name as company, count(p.*) as products, count(p.*) filter (where p.sale_price > 0) as with_mrp
from public.companies co
left join public.products p on p.company_id = co.id
where co.org_id = '1bce58f6-5c65-41e8-93f3-bd3ebb0adaeb' and co.name in ('DJC', 'Bayer')
group by co.name
order by co.name;
